type RequestInit = {
    body?: string | FormData | undefined;
    headers?: Record<string, string> | undefined;
    method?: string | undefined;
    signal?: any | undefined;
};
type Response = {
    ok: boolean;
    status: number;
    url: string;
    json(): Promise<any>;
    text(): Promise<string>;
    headers?: {
        get(name: string): string | null;
    } | undefined;
};
type FetchImpl = (url: string, init?: RequestInit) => Promise<Response>;

type FetcherConfig = {
    baseUrl?: string;
    token?: string | null;
    fetchImpl?: FetchImpl;
    headers?: Record<string, any>;
};
type FetcherOptions<TBody, THeaders, TQueryParams, TPathParams> = {
    url: string;
    method: string;
    body?: TBody | undefined;
    headers?: THeaders | undefined;
    queryParams?: TQueryParams | undefined;
    pathParams?: TPathParams | undefined;
    signal?: AbortSignal | undefined;
} & FetcherConfig;
declare function client<TData, TError, TBody, THeaders, TQueryParams, TPathParams>({ url, method, body, headers, queryParams, signal, token, baseUrl, fetchImpl }: FetcherOptions<TBody, THeaders, TQueryParams, TPathParams>): Promise<TData>;

export { type FetcherConfig as F, type FetchImpl as a, client as c };
